INSERT INTO dashboard_templates (key, name, description, category, definition, created_at, updated_at)
VALUES ('flutter-performance', 'Flutter Performance', 'App start, screen display times, slow and frozen frames, hangs, unhandled errors, memory and requests measured by the Traceway Flutter SDK', 'mobile', '{"schemaVersion":1,"widgets":[{"title":"App Start","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.start.duration","aggregation":"p75","label":"p75"},{"type":"metric","name":"app.start.duration","aggregation":"p95","label":"p95"}]}},{"title":"App Start by Type","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.start.duration","aggregation":"p75","groupBy":"start_type","label":"p75"}]}},{"title":"App Start by Release","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.start.duration","aggregation":"p75","groupBy":"service.version","label":"p75"}]}},{"title":"App Start by Country","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"app.start.duration","aggregation":"p75","groupBy":"country","label":"p75"}]}},{"title":"Time to Initial Display","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.screen.ttid","aggregation":"p75","label":"p75"},{"type":"metric","name":"app.screen.ttid","aggregation":"p95","label":"p95"}]}},{"title":"Time to Full Display","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.screen.ttfd","aggregation":"p75","label":"p75"}]}},{"title":"Slowest Screens","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"app.screen.ttid","aggregation":"p75","groupBy":"screen","label":"p75"}]}},{"title":"Slow Frames","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.frames.slow","aggregation":"sum","label":"Slow frames"},{"type":"metric","name":"app.frames.slow.total","aggregation":"sum","label":"All frames"}]}},{"title":"Frozen Frames","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.frames.frozen","aggregation":"sum","label":"Frozen frames"},{"type":"metric","name":"app.frames.frozen.total","aggregation":"sum","label":"All frames"}]}},{"title":"Janky Screens","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"app.frames.slow","aggregation":"sum","groupBy":"screen","label":"Slow frames"}]}},{"title":"Hangs","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.hang","aggregation":"sum","label":"Hangs"}]}},{"title":"Hang Duration","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.hang.duration","aggregation":"p75","label":"p75"},{"type":"metric","name":"app.hang.duration","aggregation":"p95","label":"p95"}]}},{"title":"Unhandled Errors","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.crash","aggregation":"sum","label":"Unhandled errors"}]}},{"title":"Sessions","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.session","aggregation":"sum","label":"Sessions"}]}},{"title":"Users","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.user","aggregation":"sum","label":"Users, each counted once a day"}]}},{"title":"Users Affected","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"app.user.affected","aggregation":"sum","groupBy":"issue","label":"Users"}]}},{"title":"Peak Memory per Session","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.memory.peak","aggregation":"p75","label":"p75"},{"type":"metric","name":"app.memory.peak","aggregation":"p95","label":"p95"}],"unit":"By"}},{"title":"Request Duration","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.request.duration","aggregation":"p75","label":"p75"},{"type":"metric","name":"app.request.duration","aggregation":"p95","label":"p95"}]}},{"title":"Request Duration by Host","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"app.request.duration","aggregation":"p75","groupBy":"host","label":"p75"}]}},{"title":"Failed Requests","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"app.request.failed","aggregation":"sum","label":"Failed"},{"type":"metric","name":"app.request.failed.total","aggregation":"sum","label":"All requests"}]}}]}', datetime('now'), datetime('now'))
ON CONFLICT (key) DO NOTHING;
